  "en.grammar.be-supposed-to": {
   "id": "en.grammar.be-supposed-to",
   "kind": "grammar",
   "front": "be supposed to + verb",
   "back": "<p>Diễn tả việc <strong>đã được sắp xếp / được kỳ vọng</strong> sẽ xảy ra.</p>\n<ul>\n<li><strong>is/are supposed to</strong> — theo kế hoạch thì sẽ: <em>The report is supposed to be ready by Friday.</em></li>\n<li><strong>was/were supposed to</strong> — lẽ ra phải, nhưng đã <strong>không</strong> xảy ra: <em>I was supposed to call him, but I forgot.</em></li>\n<li><strong>not supposed to</strong> — không được phép (theo quy định): <em>You're not supposed to park here.</em></li>\n</ul>",
   "pattern": "be (am/is/are/was/were) + supposed to + V",
   "tags": [
    "topic:work"
   ],
   "examples": [
    {
     "course": "workplace-english",
     "text": "The report {{c1::is supposed to}} be ready by Friday.",
     "tr": "Theo kế hoạch, báo cáo phải xong trước thứ Sáu."
    }
   ],
   "related": []
  },
